Jaký bude výsledek výrazu `a > b`, pokud třída `Cislo` definuje pouze metodu `__lt__()`?

class Cislo:
    def __init__(self, val):
        self.val = val
    def __lt__(self, other):
        return self.val < other.val

a = Cislo(5)
b = Cislo(3)
print(a > b)

